import numpy as np

def relu(x):
    return np.maximum(0.0, x)

def gelu(x):
    return 0.5 * x * (1.0 + np.tanh(np.sqrt(2 / np.pi) * (x + 0.044715 * x ** 3)))

def silu(x):
    return x / (1.0 + np.exp(-x))

xs = np.linspace(-4, 4, 801)
neg = xs < 0
h = 1e-5

relu_min, gelu_min, silu_min = float(relu(xs).min()), float(gelu(xs).min()), float(silu(xs).min())

neg_count = {}
nonzero_grad_neg = {}
for name, f in (("relu", relu), ("gelu", gelu), ("silu", silu)):
    neg_count[name] = int((f(xs)[neg] < 0).sum())
    g = (f(xs + h) - f(xs - h)) / (2 * h)
    nonzero_grad_neg[name] = int((np.abs(g[neg]) > 1e-6).sum())

def compute_kv_cache_mb(B: int, L: int, N_l: int, mode: str, **kwargs) -> float:
    if mode == 'mha':
        scalars_per_tok = 2 * kwargs['n_heads'] * kwargs['head_dim']
    elif mode == 'gqa':
        scalars_per_tok = 2 * kwargs['n_kv_heads'] * kwargs['head_dim']
    elif mode == 'mla':
        scalars_per_tok = kwargs['d_c'] + kwargs['d_r']
    else:
        raise ValueError(f"Unknown mode: {mode}")

    total_bytes = B * L * N_l * scalars_per_tok * 2  # FP16 = 2 bytes
    mb = total_bytes / (1024 * 1024)
    return round(mb, 2)

mha_mb = compute_kv_cache_mb(1, 4096, 32, 'mha', n_heads=32, head_dim=128)
mla_mb = compute_kv_cache_mb(1, 4096, 32, 'mla', d_c=512, d_r=64)
print(f"MHA: {mha_mb:.2f} MB, MLA: {mla_mb:.2f} MB")
